mapper.update:
UPDATE club_member SET role = '동호회장'
WHERE club_member_id = #{clubMemberId} AND club_id = #{clubId}
    AND role = '동호회원' AND left_at IS NULL

UPDATE club_member SET role = '동호회원'
WHERE club_id = #{clubId} AND user_id = #{userId}
    AND role = '동호회장' AND left_at IS NULL

UPDATE club_member
SET left_at = NOW(), leave_type = '내보내기', kick_reason = #{kickReason}
WHERE club_id = #{clubId} AND club_member_id = #{clubMemberId} 
    AND left_at IS NULL
